import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from shuffle ----
/** mulberry32: a fixed seed keeps every shuffle identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const random = seededRandom(20260813);

const barCount = 24;

/** `order[position]` is the element currently sitting there; `i` is the settled boundary. */
type ShuffleFrame = { order: number[]; i: number; j: number };

function fisherYatesFrames(count: number): ShuffleFrame[] {
  const order = Array.from({ length: count }, (_, index) => index);
  const frames: ShuffleFrame[] = [{ order: order.slice(), i: count, j: -1 }];

  for (let i = count - 1; i > 0; --i) {
    const j = Math.floor(random() * (i + 1));
    [order[i], order[j]] = [order[j], order[i]];
    frames.push({ order: order.slice(), i, j });
  }

  frames.push({ order: order.slice(), i: 0, j: -1 });
  return frames;
}

const shuffleFrames = fisherYatesFrames(barCount);

const matrixSize = 8;
const trials = 4000;
const expectedCount = trials / matrixSize;

function fisherYatesShuffle(values: number[]): number[] {
  for (let i = values.length - 1; i > 0; --i) {
    const j = Math.floor(random() * (i + 1));
    [values[i], values[j]] = [values[j], values[i]];
  }
  return values;
}

// Insertion sort written out rather than handed to Array.prototype.sort: the standard leaves
// the sorting algorithm to the engine, so the exact bias would not be reproducible.
function comparatorShuffle(values: number[]): number[] {
  for (let k = 1; k < values.length; ++k) {
    const item = values[k];
    let m = k - 1;
    while (m >= 0 && random() - 0.5 > 0) {
      values[m + 1] = values[m];
      --m;
    }
    values[m + 1] = item;
  }
  return values;
}

/** counts[element][position]: how often element i lands at position j over every trial. */
function biasMatrix(shuffle: (values: number[]) => number[]): number[][] {
  const counts = Array.from({ length: matrixSize }, () => new Array<number>(matrixSize).fill(0));
  for (let trial = 0; trial < trials; ++trial) {
    shuffle(Array.from({ length: matrixSize }, (_, index) => index)).forEach((element, position) => {
      counts[element][position] += 1;
    });
  }
  return counts;
}

const fisherYatesMatrix = biasMatrix(fisherYatesShuffle);
const comparatorMatrix = biasMatrix(comparatorShuffle);

const maxCount = Math.max(
  ...fisherYatesMatrix.flat(),
  ...comparatorMatrix.flat()
);

const MARGIN = { top: 74, right: 14, bottom: 40, left: 34 };
const GAP = 42;
const MAX_SIDE = 250;

const panels = [
  { title: 'Fisher-Yates', note: 'uniform', matrix: fisherYatesMatrix },
  { title: 'sort by random comparator', note: 'biased', matrix: comparatorMatrix }
];

const indices = d3.range(matrixSize);

export default function ShuffleBias({ width }: { width: number }) {
  const available = Math.max(1, width - MARGIN.left - MARGIN.right - GAP);
  const side = Math.max(1, Math.min(available / 2, MAX_SIDE));
  const cell = side / matrixSize;
  const height = Math.round(MARGIN.top + side + MARGIN.bottom);

  const color = useMemo(() => d3.scaleSequential([0, maxCount], d3.interpolateInferno), []);

  const ramp = useMemo(
    () => d3.range(48).map((i) => ({ offset: i, fill: color((i / 47) * maxCount) })),
    [color]
  );

  if (width === 0) return null;

  const rampWidth = Math.min(200, side * 0.9);
  const legendX = MARGIN.left;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={`Two heatmaps over ${trials} shuffles of ${matrixSize} elements: Fisher-Yates lands every element uniformly, while sorting by a random comparator leaves a bright diagonal`}
      style={{ display: 'block', font: '10px sans-serif' }}
    >
      <text x={MARGIN.left} y={14} fill="var(--muted)">
        {d3.format(',')(trials)} shuffles of {matrixSize} elements; a fair shuffle expects{' '}
        {expectedCount} in every cell
      </text>

      {/* Shared ramp: the two panels are only comparable if one scale covers both. */}
      <g transform={`translate(${legendX},24)`}>
        {ramp.map(({ offset, fill }) => (
          <rect
            key={offset}
            x={(offset / 48) * rampWidth}
            width={rampWidth / 48 + 0.5}
            height={8}
            fill={fill}
          />
        ))}
        <text y={20} fill="var(--muted)">
          0
        </text>
        <text x={(expectedCount / maxCount) * rampWidth} y={20} fill="var(--muted)" textAnchor="middle">
          {expectedCount}
        </text>
        <text x={rampWidth} y={20} fill="var(--muted)" textAnchor="end">
          {d3.format(',')(maxCount)}
        </text>
      </g>

      {panels.map((panel, panelIndex) => (
        <g
          key={panel.title}
          transform={`translate(${MARGIN.left + panelIndex * (side + GAP)},${MARGIN.top})`}
        >
          <text y={-10} fill="var(--text)">
            {panel.title}
            <tspan fill="var(--accent)"> — {panel.note}</tspan>
          </text>

          {panel.matrix.map((row, element) =>
            row.map((count, position) => (
              <rect
                key={`${element}-${position}`}
                x={position * cell}
                y={element * cell}
                width={cell + 0.5}
                height={cell + 0.5}
                fill={color(count)}
              >
                <title>{`element ${element} landed at position ${position} ${count} times`}</title>
              </rect>
            ))
          )}

          <g fill="var(--muted)">
            {indices.map((index) => (
              <text
                key={index}
                x={index * cell + cell / 2}
                y={side + 12}
                textAnchor="middle"
              >
                {index}
              </text>
            ))}
            <text x={side / 2} y={side + 26} textAnchor="middle">
              final position
            </text>
            {panelIndex === 0 &&
              indices.map((index) => (
                <text key={index} x={-6} y={index * cell + cell / 2} dy="0.32em" textAnchor="end">
                  {index}
                </text>
              ))}
          </g>
        </g>
      ))}

      <text
        transform={`translate(12,${MARGIN.top + side / 2}) rotate(-90)`}
        textAnchor="middle"
        fill="var(--muted)"
      >
        original element
      </text>
    </svg>
  );
}
